pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 number,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 seq,
        bytes32 batcherHash,
        uint256 overhead,
        uint256 scalar
    ) public {
        // Rule: a call to setL1BlockValues made by the hardcoded DEPOSITOR_ACCOUNT
        // must ALWAYS revert in the reference (which checks the zero-initialized
        // storage variable), and never revert in the buggy mutant (which checks
        // the constant, so the depositor's own call succeeds).
        vm.prank(c.DEPOSITOR_ACCOUNT());
        bool ok;
        try c.setL1BlockValues(number, timestamp, basefee, hash, seq, batcherHash, overhead, scalar) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "depositor call must always revert");
    }
}

