pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        address actor,
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // _timestamp must be nonzero so that "timestamp unchanged (0)" differs from "timestamp stored"
        _timestamp = uint64(bound(_timestamp, 1, type(uint64).max));
        // The reference only ever accepts calls from its depositorAccount; with the default
        // constructor the depositor account is address(0). Prank it so the call succeeds and
        // the post-state (not just the revert path) is exercised.
        vm.prank(address(0));
        try c.setL1BlockValues(
            _number, _timestamp, _basefee, _hash,
            _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar
        ) {
            // Call succeeded: reference leaves timestamp at its initial 0, never equal to _timestamp.
            assertTrue(c.timestamp() != _timestamp);
        } catch {
            // Call reverted: no state change occurred, timestamp stays 0 != _timestamp.
            assertTrue(c.timestamp() != _timestamp);
        }
    }
}

